-- VELLIOR baseline migration (apply once in Supabase SQL Editor)
create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum ('customer','admin','operator'); exception when duplicate_object then null; end $$;
do $$ begin create type public.order_status as enum ('pending_payment','paid','processing','shipped','delivered','cancelled','refunded'); exception when duplicate_object then null; end $$;
do $$ begin create type public.payment_status as enum ('pending','processing','approved','rejected','expired','cancelled','refunded'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', consent_terms_at timestamptz, consent_privacy_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.user_roles(user_id uuid primary key references auth.users(id) on delete cascade, role public.app_role not null default 'customer', created_at timestamptz not null default now());
create table if not exists public.categories(id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, description text, published boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(), category_id uuid references public.categories(id) on delete set null, name text not null, slug text unique not null, description text, sku text unique not null, price_cents integer not null check(price_cents >= 0), sale_price_cents integer check(sale_price_cents is null or (sale_price_cents >= 0 and sale_price_cents <= price_cents)), stock integer not null default 0 check(stock >= 0), low_stock_threshold integer not null default 3 check(low_stock_threshold >= 0), published boolean not null default false, featured boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.product_images(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, storage_path text not null, alt_text text, sort_order integer not null default 0);
create table if not exists public.addresses(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, label text, recipient_name text not null, postal_code text not null, street text not null, number text not null, complement text, neighborhood text not null, city text not null, state text not null, created_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(), order_number text unique not null default ('VEL-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), user_id uuid not null references auth.users(id), address_snapshot jsonb not null default '{}'::jsonb, subtotal_cents integer not null check(subtotal_cents >= 0), discount_cents integer not null default 0 check(discount_cents >= 0), shipping_cents integer not null default 0 check(shipping_cents >= 0), total_cents integer not null check(total_cents >= 0), status public.order_status not null default 'pending_payment', created_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id) on delete set null, product_name_snapshot text not null, sku_snapshot text not null, unit_price_cents integer not null check(unit_price_cents >= 0), quantity integer not null check(quantity > 0));
create table if not exists public.payments(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, provider text not null, provider_payment_id text, status public.payment_status not null default 'pending', amount_cents integer not null check(amount_cents >= 0), idempotency_key text unique not null, raw_reference text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.audit_log(id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity text not null, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists products_public_idx on public.products(published,created_at desc); create index if not exists orders_user_idx on public.orders(user_id,created_at desc); create index if not exists order_items_order_idx on public.order_items(order_id); create index if not exists payments_order_idx on public.payments(order_id);
create or replace function public.has_role(required_role public.app_role) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.user_roles where user_id=(select auth.uid()) and role=required_role) $$;
revoke all on function public.has_role(public.app_role) from public; grant execute on function public.has_role(public.app_role) to authenticated, anon;
alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.product_images enable row level security; alter table public.addresses enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.payments enable row level security; alter table public.audit_log enable row level security;
drop policy if exists profiles_select_self on public.profiles; create policy profiles_select_self on public.profiles for select to authenticated using(id=(select auth.uid()) or public.has_role('admin'));
drop policy if exists profiles_update_self on public.profiles; create policy profiles_update_self on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
drop policy if exists roles_select_self_admin on public.user_roles; create policy roles_select_self_admin on public.user_roles for select to authenticated using(user_id=(select auth.uid()) or public.has_role('admin'));
drop policy if exists categories_public_admin on public.categories; create policy categories_public_admin on public.categories for select using(published or public.has_role('admin'));
drop policy if exists categories_admin_write on public.categories; create policy categories_admin_write on public.categories for all to authenticated using(public.has_role('admin')) with check(public.has_role('admin'));
drop policy if exists products_public_admin on public.products; create policy products_public_admin on public.products for select using(published or public.has_role('admin'));
drop policy if exists products_admin_write on public.products; create policy products_admin_write on public.products for all to authenticated using(public.has_role('admin')) with check(public.has_role('admin'));
drop policy if exists images_public_admin on public.product_images; create policy images_public_admin on public.product_images for select using(exists(select 1 from public.products p where p.id=product_id and (p.published or public.has_role('admin'))));
drop policy if exists images_admin_write on public.product_images; create policy images_admin_write on public.product_images for all to authenticated using(public.has_role('admin')) with check(public.has_role('admin'));
drop policy if exists addresses_own on public.addresses; create policy addresses_own on public.addresses for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
drop policy if exists orders_read_own_admin on public.orders; create policy orders_read_own_admin on public.orders for select to authenticated using(user_id=(select auth.uid()) or public.has_role('admin'));
drop policy if exists items_read_own_admin on public.order_items; create policy items_read_own_admin on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and (o.user_id=(select auth.uid()) or public.has_role('admin'))));
drop policy if exists payments_admin_read on public.payments; create policy payments_admin_read on public.payments for select to authenticated using(public.has_role('admin'));
drop policy if exists audit_admin_read on public.audit_log; create policy audit_admin_read on public.audit_log for select to authenticated using(public.has_role('admin'));
grant select on public.products,public.categories,public.product_images to anon,authenticated; grant insert,update,delete on public.products,public.categories,public.product_images to authenticated; grant select,insert,update,delete on public.profiles,public.addresses to authenticated; grant select on public.user_roles,public.orders,public.order_items,public.payments,public.audit_log to authenticated;
-- Deliberately no client INSERT policies for roles, orders, payments, order items or audit logs.
-- Provisioning the first admin and creating orders must happen from trusted server-side procedures.

